import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, vec3, uniform, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, OctahedronGeometry, PointLight, AmbientLight, Color } = ctx.THREE;

  const rootGroup = new Group();
  const interactiveGroup = new Group();
  rootGroup.add(interactiveGroup);

  const timelines = [];
  const disposables = [];

  // 1. Stage Backdrop (designed-for-dark backdrop containing vertical gradient)
  const backplateGeo = new PlaneGeometry(8, 6.5);
  disposables.push(backplateGeo);

  const backplateMat = new MeshBasicNodeMaterial();
  const gradNode = mix(
    color(new Color(config.visualSpec?.colors?.ink || '#16161d')),
    color(new Color(config.visualSpec?.colors?.surface || '#0b0b10')),
    uv().y
  );
  backplateMat.colorNode = gradNode;
  backplateMat.depthWrite = false;

  const backplateMesh = new Mesh(backplateGeo, backplateMat);
  backplateMesh.position.z = -2.0;
  rootGroup.add(backplateMesh);

  // 2. Local Studio Lighting for Machined Metal Aesthetics
  const keyLight = new PointLight('#e8ecf2', 1.4, 15);
  keyLight.position.set(2, 2, 2.5);
  rootGroup.add(keyLight);

  const rimLight = new PointLight('#ff2a38', 0.9, 10);
  rimLight.position.set(-2, -2, 1.5);
  rootGroup.add(rimLight);

  const fillAmbient = new AmbientLight('#16161d', 0.4);
  rootGroup.add(fillAmbient);

  // 3. Tessellated Interactive Parallax Rule Plane
  const ruleGeo = new PlaneGeometry(3.5, 0.8, 64, 64);
  disposables.push(ruleGeo);

  const ruleMat = new MeshStandardNodeMaterial({
    roughness: 0.52,
    metalness: 0.55,
    transparent: true,
  });

  const displacementAmount = uniform(0.18);

  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  interactiveGroup.add(ruleMesh);

  // Load Textures and setup displacement TSL
  if (config.imageUrl && config.depthMapUrl) {
    Promise.all([
      ctx.textureLoader.loadTexture(config.imageUrl),
      ctx.textureLoader.loadTexture(config.depthMapUrl)
    ]).then(([imgTex, depthTex]) => {
      ruleMat.map = imgTex;

      const depthTexNode = texture(depthTex);
      ruleMat.positionNode = positionLocal.add(
        vec3(0, 0, depthTexNode.r.mul(displacementAmount))
      );

      ruleMat.needsUpdate = true;
    }).catch(err => console.error("Error loading rule assets:", err));
  }

  // 4. Center 3D Jewel Accent (Octahedron with Signal Red glow)
  const jewelGeo = new OctahedronGeometry(0.08, 0);
  disposables.push(jewelGeo);

  const jewelMat = new MeshStandardNodeMaterial({
    color: config.visualSpec?.colors?.accent || '#ff2a38',
    emissive: config.visualSpec?.colors?.accent || '#ff2a38',
    emissiveIntensity: 1.8,
    roughness: 0.1,
    metalness: 0.9
  });
  disposables.push(jewelMat);

  const jewelMesh = new Mesh(jewelGeo, jewelMat);
  jewelMesh.position.set(0, 0, 0.08);
  interactiveGroup.add(jewelMesh);

  // Constantly rotating jewel
  const jewelRotateTL = gsap.to(jewelMesh.rotation, {
    y: Math.PI * 2,
    z: Math.PI,
    duration: 6,
    repeat: -1,
    ease: "none"
  });
  timelines.push(jewelRotateTL);

  // 5. Cinematic Fallback / Parallax Primitive Integration via context API
  const parallaxPrim = ctx.primitives['depth-rotate']
    ? ctx.primitives['depth-rotate'](interactiveGroup, { intensity: 0.6 })
    : null;

  // 6. Interactive State Handling & Gestures
  let pointerTargetY = 0;
  let pointerTargetX = 0;

  const hoverInTL = gsap.timeline({ paused: true });
  hoverInTL.to(interactiveGroup.position, {
    z: 0.15,
    duration: 0.5,
    ease: "power2.out"
  });
  timelines.push(hoverInTL);

  rootGroup.userData.handlers = {
    pointerenter: () => {
      hoverInTL.play();
    },
    pointerleave: () => {
      hoverInTL.reverse();
      gsap.to(interactiveGroup.rotation, { x: 0, y: 0, duration: 0.6, ease: "power2.out" });
    },
    pointermove: (event) => {
      if (event.pointerPoint) {
        pointerTargetX = event.pointerPoint.x * 0.18;
        pointerTargetY = event.pointerPoint.y * 0.18;
        gsap.to(interactiveGroup.rotation, {
          y: pointerTargetX,
          x: -pointerTargetY,
          duration: 0.4,
          ease: "power1.out"
        });
      }
    },
    click: () => {
      const clickTL = gsap.timeline();
      clickTL.to(interactiveGroup.scale, {
        x: 0.95, y: 0.95, z: 0.95,
        duration: 0.1,
        ease: "power2.out"
      });
      clickTL.to(interactiveGroup.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.4,
        ease: "elastic.out(1, 0.3)"
      });
      timelines.push(clickTL);

      ctx.emit('hub-features.select', { id: config.id });
    }
  };

  // 7. Resource Management (Cleanup)
  rootGroup.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (parallaxPrim && typeof parallaxPrim.cleanup === 'function') {
      parallaxPrim.cleanup();
    }
    disposables.forEach(d => d.dispose());
    ruleMat.dispose();
  };

  return rootGroup;
}
